#include <bits/stdc++.h>
#include <cassert>

using namespace std;
using ll = long long;

#define all(x) (x).begin(), (x).end()
#define sz(x) (int)(x).size()
#define pb push_back

void solve() {
    ll n, k; cin >> n >> k;
    ll top = 0;
    for (int x = 1; x <= n / 2; x++) {
        top += x;
        if (2 * x <= n - 1) top += x;
    }
    top *= 2;
    if (k % 2 == 1 || k < 2 * (n - 1) || k > top) {
        cout << "-1\n";
        return;
    } 
    if (n == 2) {
        cout << "1 2\n";
        return;
    }
    vector<int> cnt(2, (n - 1) / 2);
    if (n % 2 == 0) cnt[1]++;
    ll cur = top;
    cur /= 2;
    k /= 2;
    for (int i = 0; ; i++) {
        int id = i % 2;
        if (cnt[id] > 1 && cur - (cnt[id] - 1) >= k) {
            cur -= (cnt[id] - 1);
            cnt.pb(1);
            cnt[id]--;
        } else if (cnt[id] > 1 || cur == k) {
            vector<pair<int, int>> edges;
            int cr = 2;
            vector<int> startv(sz(cnt));
            for (int j = 0; j < sz(cnt); j++) {
                startv[j] = cr;
                if (j != id) {
                    int prv = 1;
                    for (int x = 0; x < cnt[j]; x++) {
                        edges.pb({prv, cr++});
                        prv = cr - 1;
                    }
                } else {
                    int prv = 1, start = cr;
                    for (int x = 0; x < cnt[j] - 1; x++) {
                        edges.pb({prv, cr++});
                        prv = cr - 1;
                    }
                    int was = cnt[j];
                    int neww = was - (cur - k);
                    if (neww == 1) edges.pb({1, cr++});
                    else edges.pb({start + (neww - 2), cr++});
                }
            }
            set<pair<int, int>> st;
            for (int j = 0; j < sz(cnt); j++) st.insert({cnt[j], j});
            vector<int> per(n + 1);
            per[1] = 1;
            int lst = -1;
            for (int x = 2; x <= n; x++) {
                auto it = --st.end();
                while ((*it).second == lst) it--;
                auto [c,id] = *it;
                st.erase(it);
                per[startv[id]] = x;
                startv[id]++;
                lst = id;
                assert(cnt[id] > 0);
                cnt[id]--;
                st.insert({cnt[id], id});
            }
            for (auto &[u, v] : edges) {
                u = per[u]; v = per[v];
                cout << u << ' ' << v << '\n';
            }
            break;
        }
    }
}

